        "개요": "특유의 정교하고 아름다운 문체로 삶에 대한 폭넓은 통찰을 보여주며 한국문학을 대표하는 작가로 자리매김한 김연수의 소설집 『눈 내리는 삼일포』를 문학동네에서 펴낸다. 『이토록 평범한 미래』(문학동네, 2022) 이후 4년 만에 묶어내는 일곱번째 소설집으로, 한층 스펙트럼이 넓어진 9편의 소설이 실렸다.",
